class CustomError(Exception):
    pass # pass statement is a placeholder that does nothing when executed
def check_value(value):
    if value < 0:
        raise CustomError("Value must be non-negative ! " )
try :
    check_value(-1)
except CustomError as e:
    print("Error :" , e)

age = -5
class AgeError(Exception):
    pass
def check_age(age):
    if age < 0:
        raise AgeError("Age negative nahi ho sakti: " + str(age))
    print("Age theek hai:", age)
try:
    check_age(age)
except AgeError as e:
    print("AgeError pakri gayi:", e)
